#!/usr/bin/env python3
from pwn import *
import gmpy2
from gmpy2 import mpz, isqrt, is_square, gcd

def phi_fermat_factorization(n, max_diff=1000):
    n = mpz(n)
    a = isqrt(n)

    for diff in range(max_diff):
        for a_test in [a - diff, a + diff]:
            b2 = a_test*a_test - n
            if is_square(b2):
                b = isqrt(b2)
                p = a_test + b
                q = a_test - b
                if p * q == n:
                    phi_p = p - 1
                    phi_q = q - 1
                    if gcd(phi_p, phi_q) > 1:
                        return p, q
    return None, None

